{
  "county_id": "HVA08",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Proposed: Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "Pirkanmaa wellbeing services county's age-standardised cancer mortality ratio is 1.022, about 27.2 more deaths a year than expected, and the optimiser scenario for timed-pathways postpones 21.9 deaths a year (range 3.3-44) at an assumed cost of EUR 823,365 a year, staying in the portfolio in 81% of sensitivity runs.",
      "owner_role": "Accountable owner: Wellbeing services county, coordinated nationally by FICAN.",
      "indicator": "Indicator to monitor: Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants.",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Proposed: Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Pirkanmaa wellbeing services county's cervical screening participation is 71.4% against the 80% target, and the optimiser scenario for self-sampling is expected to add 1.5-4.5 percentage points, closing about 35% of the gap, at an assumed cost of EUR 329,346 a year.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Proposed: Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Pirkanmaa wellbeing services county's colorectal screening participation is 75.9% against the 80% target, and the optimiser scenario for screening-reminders is expected to add 1.5-4.1 percentage points, closing about 73% of the gap, at an assumed cost of EUR 219,564 a year.",
      "owner_role": "Accountable owner: Wellbeing services county screening unit.",
      "indicator": "Indicator to monitor: Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "timed-pathways: Danish evidence is before/after without a control group. Patients left outside the pathway waited 4 days longer, so coverage must be monitored."
}

